List<String> refundAll(List<String> ids) throws Exception {
    try (ExecutorService pool = Executors.newFixedThreadPool(8)) {     // 1. 8 threads = at most 8 calls
        CompletionService<String> done = new ExecutorCompletionService<>(pool);
        for (String id : ids) done.submit(() -> issuer.refund(id));     // 2. every task queued up front
