suspend fun refundAll(ids: List<String>) = coroutineScope {
    val queue = produce { for (id in ids) send(id) }   // closed when the block ends
    repeat(3) {
        launch { for (id in queue) refund(id) }        // each id goes to one worker
    }
}   // coroutineScope waits for the producer and all three workers

