// Java equivalent: a pool of 3 threads, and invokeAll to wait for every task
void refundAll(List<String> ids) throws Exception {
    try (ExecutorService pool = Executors.newFixedThreadPool(3)) {
        List<Callable<Void>> tasks = ids.stream()
            .<Callable<Void>>map(id -> () -> { refund(id); return null; })
            .toList();
        for (Future<Void> f : pool.invokeAll(tasks)) f.get();   // rethrows the first failure
    }   // unlike coroutineScope, the other refunds are not cancelled on a failure
}

